/// 5.4 — A take is flagged anomalous when its peak laugh duration falls at
/// least two standard deviations below the mean of the joke's other takes, and
/// never when fewer than three other takes exist.
let takeAnomaly_5_4 = RequirementCase(id: "5.4") {
    let joke = UUID()
